const rows = $input.all();
const slots = rows
  .filter(r => String(r.json['Booked'] || '').trim().toUpperCase() !== 'Y')
  .map(r => ({
    id        : String(r.json['ID']         || '').trim(),
    tanggal   : String(r.json['Tanggal']    || '').trim(),
    jamMulai  : String(r.json['JamMulai']   || '').trim(),
    jamSelesai: String(r.json['JamSelesai'] || '').trim(),
    booked    : false,
  }))
  .filter(s => s.id && s.tanggal && s.jamMulai && s.jamSelesai);
return [{ json: { slots } }];

const body = $input.first().json.body || $input.first().json;
const required = ['idBooking','tanggal','noWaAnak','namaAnak','namaOrangTua','asalKota','sekolah','kelas','kurikulumSekolah','targetUniJurusan','jamMulai','jamSelesai','slotId'];
const missing = required.filter(k => !body[k] || String(body[k]).trim() === '');
if (missing.length > 0) throw new Error('Missing fields: ' + missing.join(', '));
const wa = String(body.noWaAnak).trim();
if (!/^(08\d{8,12}|628\d{8,12})$/.test(wa)) throw new Error('Format noWaAnak tidak valid: ' + wa);
return [{ json: {
  idBooking        : String(body.idBooking).trim(),
  tanggal          : String(body.tanggal).trim(),
  noWaAnak         : wa,
  namaAnak         : String(body.namaAnak).trim(),
  namaOrangTua     : String(body.namaOrangTua).trim(),
  asalKota         : String(body.asalKota).trim(),
  sekolah          : String(body.sekolah).trim(),
  kelas            : String(body.kelas).trim(),
  kurikulumSekolah : String(body.kurikulumSekolah).trim(),
  targetUniJurusan : String(body.targetUniJurusan).trim(),
  bimbingan        : 'University Mock Interview',
  jamMulai         : String(body.jamMulai).trim(),
  jamSelesai       : String(body.jamSelesai).trim(),
  slotId           : String(body.slotId).trim(),
  status           : 'Pending',
  timestamp        : body.timestamp || Math.floor(Date.now() / 1000),
}}];

const slotRows = $input.all();
const payload  = $('Validate Payload').first().json;
if (slotRows.length === 0) return [{ json: { slotTaken: true, reason: 'SLOT_NOT_FOUND', ...payload } }];
const slot   = slotRows[0].json;
const Booked = String(slot['Booked'] || '').trim().toUpperCase();
if (Booked === 'Y') return [{ json: { slotTaken: true, reason: 'SLOT_TAKEN', ...payload } }];
return [{ json: { slotTaken: false, rowNumber: slot.row_number, ...payload } }];

const query = $input.first().json.query || {};
const id     = String(query.id     || '').trim();
const action = String(query.action || '').trim().toLowerCase();
const skipFree = String(query.skip_free || '').trim() === '1';
if (!id)                                    throw new Error('Missing booking ID');
if (!['confirm','reject'].includes(action)) throw new Error('Invalid action: ' + action);
return [{ json: { id, action, skipFree } }];

const rows = $input.all();
if (rows.length === 0) {
  const id = $('Parse Confirm Request').first().json.id;
  return [{ json: { bookingFound: false, id } }];
}
return rows.map(r => ({ json: { ...r.json, bookingFound: true } }));

const configRows  = $input.all();
const bookingRow  = $('Read Booking by ID (Confirm)').first().json;
const { id, action, skipFree } = $('Parse Confirm Request').first().json;

const cfg = {};
configRows.forEach(r => {
  const k = String(r.json['Key']   || '').trim();
  const v = String(r.json['Value'] || '').trim();
  if (k) cfg[k] = v;
});

const status = String(bookingRow['Status'] || '').trim();

return [{ json: {
  id,
  action,
  skipFree         : skipFree || false,
  alreadyProcessed : status !== 'Pending',
  status,
  namaAnak         : String(bookingRow['Nama Anak']   || '').trim(),
  noWaAnak         : String(bookingRow['No WA Anak']  || '').trim(),
  tanggal          : String(bookingRow['Tanggal']     || '').trim(),
  jamMulai         : String(bookingRow['Jam Mulai']   || '').trim(),
  jamSelesai       : String(bookingRow['Jam Selesai'] || '').trim(),
  slotId           : String(bookingRow['Slot ID']     || '').trim(),
  nominalBiaya     : cfg['NOMINAL_BIAYA']   || '1.000.000',
  namaBank         : cfg['NAMA_BANK']       || 'BCA',
  nomorRekening    : cfg['NOMOR_REKENING']  || '1820111111',
  atasNama         : cfg['ATAS_NAMA']       || 'Samuel Oscar',
  deadlineHari     : cfg['DEADLINE_HARI']   || '1',
}}];

const d = $input.first().json;
return [{ json: { html:
  '<!doctype html><html lang="id"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>Sudah Diproses</title><style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:system-ui,sans-serif;background:#f9f9f8;display:flex;align-items:center;justify-content:center;min-height:100vh;padding:1rem}.card{background:#fff;border-radius:16px;padding:2rem 1.5rem;max-width:360px;width:100%;text-align:center;box-shadow:0 2px 16px rgba(0,0,0,.08)}.icon{font-size:3rem;margin-bottom:1rem}h1{font-size:1.25rem;font-weight:700;margin-bottom:.5rem}p{color:#6b6a65;font-size:.875rem;line-height:1.6;margin-top:.5rem}</style></head><body><div class="card"><div class="icon">ℹ️</div><h1>Sudah Diproses</h1><p>Booking <strong>' + d.id + '</strong> sudah diproses sebelumnya.<br/>Status saat ini: <strong>' + d.status + '</strong></p></div></body></html>'
}}];

const d = $('Build Confirm Data').first().json;
return [{ json: { html:
  '<!doctype html><html lang="id"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>Booking Dikonfirmasi</title><style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:system-ui,sans-serif;background:#f9f9f8;display:flex;align-items:center;justify-content:center;min-height:100vh;padding:1rem}.card{background:#fff;border-radius:16px;padding:2rem 1.5rem;max-width:360px;width:100%;text-align:center;box-shadow:0 2px 16px rgba(0,0,0,.08)}.icon{font-size:3rem;margin-bottom:1rem}h1{font-size:1.25rem;font-weight:700;margin-bottom:.5rem}p{color:#6b6a65;font-size:.875rem;line-height:1.6;margin-top:.5rem}</style></head><body><div class="card"><div class="icon">✅</div><h1>Booking Dikonfirmasi</h1><p><strong>' + d.namaAnak + '</strong><br/>' + d.tanggal + ' · ' + d.jamMulai + '–' + d.jamSelesai + ' WIB</p><p>WA konfirmasi + info pembayaran sudah dikirim ke murid.</p></div></body></html>'
}}];

const d = $('Build Confirm Data').first().json;
return [{ json: { html:
  '<!doctype html><html lang="id"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>Booking Ditolak</title><style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:system-ui,sans-serif;background:#f9f9f8;display:flex;align-items:center;justify-content:center;min-height:100vh;padding:1rem}.card{background:#fff;border-radius:16px;padding:2rem 1.5rem;max-width:360px;width:100%;text-align:center;box-shadow:0 2px 16px rgba(0,0,0,.08)}.icon{font-size:3rem;margin-bottom:1rem}h1{font-size:1.25rem;font-weight:700;margin-bottom:.5rem}p{color:#6b6a65;font-size:.875rem;line-height:1.6;margin-top:.5rem}</style></head><body><div class="card"><div class="icon">❌</div><h1>Booking Ditolak</h1><p><strong>' + d.namaAnak + '</strong><br/>' + d.tanggal + ' · ' + d.jamMulai + '–' + d.jamSelesai + ' WIB</p><p>WA pemberitahuan sudah dikirim ke murid. Slot dikembalikan.</p></div></body></html>'
}}];

const rows = $input.all();
const currentId = $('Parse Confirm Request').first().json.id;
const d = $('Build Confirm Data').first().json;

// Cari booking lain utk slot yang sama yg sudah Status=Confirmed
const confirmed = rows.filter(r => {
  const status    = String(r.json['Status']     || '').trim();
  const bookingId = String(r.json['ID Booking'] || '').trim();
  return status === 'Confirmed' && bookingId !== currentId;
});

const hasConflict = confirmed.length > 0;
// showConflictPage: tampilkan halaman konflik KECUALI jika ini adalah
// force-reject dari halaman konflik itu sendiri (skip_free=1 & action=reject)
const showConflictPage = hasConflict && !(d.skipFree === true && d.action === 'reject');

if (hasConflict) {
  const w = confirmed[0].json;
  return [{ json: {
    hasConflict,
    showConflictPage,
    winnerNama     : String(w['Nama Anak']      || '').trim(),
    winnerOrangTua : String(w['Nama Orang Tua'] || '').trim(),
    winnerNoWa     : String(w['No WA Anak']     || '').trim(),
    winnerSekolah  : String(w['Sekolah']        || '').trim(),
    winnerKelas    : String(w['Kelas']          || '').trim(),
    winnerIdBooking: String(w['ID Booking']     || '').trim(),
    ...d,
  }}];
}
return [{ json: { hasConflict: false, showConflictPage: false, ...d } }];
